// Auto-end a finished fleet worker (#920 / #1379). Two triggers drop a worker pane into a resting
// state (done / needs-attention / blocked) instead of leaving a dead console in the grid:
//   - `pty_exit_{paneId}` — the shell exited (legacy; rarely fires for the long-lived REPL).
//   - `bsc-done` (#1379) — a finished worker self-reports via `done.log`; we poll `read_done_panes`
//     and reap, additionally `pty_kill`-ing the still-live session.
// Either way the TRIGGER is only the prompt to evaluate; the verdict comes from plan.db with
// coord.log as a tiebreaker — NOT the worker's say-so — and it is DECIDED IN RUST
// (`worker_end_verdicts`), not here. This module reports what it alone knows (which pane exited, how,
// and when) and renders the answer. The ended state is persisted + recovery-gated, so a restart never re-opens a finished
// worker. Mounted once at the app root.
//
// THIS MODULE WRITES TO NO SESSION'S STDIN. It ends and reaps panes; it never types at one. Two raw
// `pty_write` calls into the DIRECTOR's pane lived here until
// #the-fleet-went-pull-but-nobody-told-the-director-to-pull — a raw invoke, so the injector ratchet
// (which matches `injectPrompt` imports) could not see them, and `pty_kill` reads as the same kind of
// call at a glance. If you are about to add a message for a director, it belongs in a queue the
// director PULLS (`bsc logs waiting`, `bsc fleet list`), not in its input.

import type { StopReason } from "@/app/console/lib/paneStops";
import { useEffect, useRef } from "react";
import { listen } from "@tauri-apps/api/event";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { logsDonePanes, logsPaneActivity } from "@/shared/lib/core/logsBridge";
import { usePoll } from "@/shared/hooks/usePoll";
import { verdictFromPulls, planNextProbe, isDue } from "@/shared/lib/fleet/prProbe";
import { useLogStream } from "@/shared/hooks/useLogStream";
import { useAppStore } from "@/store";
import type { PaneIdentityTab } from "@/app/console/lib/paneIdentity";
import { emptyCoordState } from "@/shared/lib/fleet/coordination";
import { readCoordState } from "@/shared/lib/fleet/useCoordLog";
import type { WorkerEndVerdict } from "@/shared/lib/fleet/workerEnd";
import { decideWorkerAutoEnd, DEFAULT_AUTO_END_THRESHOLDS } from "@/shared/lib/fleet/workerAutoEnd";
import { log } from "@/shared/lib/core/log";

/** One pane's latest turn-boundary state, as `bsc logs pane-activity` (`logs::PaneActivity`)
 *  returns it — typed locally so this shared module doesn't import the app layer. */
interface ActivityRow { pane: string; state: string; at: number }

// The close-NUDGE is gone (#session-stop-is-honoured). It used to `pty_write` a "run bsc-done" prompt
// into an idle, question-free, work-complete worker — i.e. the app typing at a session that had just
// finished. That never fired in practice, because `bsc-defer` refused a worker's Stop and it could not
// reach "idle with work complete" in the first place. Removing the hook would have SWITCHED IT ON, so
// a finished worker would have stopped and immediately been re-prompted: the exact behaviour this item
// exists to end, arriving through a different door.
//
// The pane still reaches its resting state — `evaluateExit` is called directly instead. That is the
// same verdict from the same source (plan.db via `worker_end_verdicts`, never the worker's say-so); the
// nudge only ever existed to make the worker call `bsc-done` so this ran. Cutting out the round trip
// through the agent is strictly better: no injection, no token spend, and no dependence on the session
// still being alive to answer. The app updating its OWN UI is not the app driving a session.

/** How idle-poll ticks: every 15s. The close-nudge threshold is 60s, so this is responsive enough. */
// #3643: the idle close-nudge is event-driven — it re-checks when a worker's turn state changes
// (`activity`), coord changes, or a worker self-reports done, + a slow backstop; not a 15s clock.

/**
 * Evaluate a worker's owned issues and mark the pane ended accordingly. `opts.kill` also kills the
 * PTY — used by the `bsc-done` path, where the worker is still live (the `pty_exit` path leaves it
 * false, since the shell already exited).
 */
/** The `pty_exit_<pane>` payload Rust emits (`console::pty::pump::SessionEnd`).
 *
 *  `reason` is kebab-cased on the wire so its spellings ARE the `StopReason` union's — no mapping
 *  table, and a rename on either side fails to compile rather than silently degrading to "finished".
 */
interface SessionEndPayload {
  reason?: StopReason;
  detail?: string;
  lastOutput?: string;
}

/**
 * The resting-state verdict for each stream, DECIDED IN RUST
 * (`the-worker-end-is-classified-where-the-pty-exits`).
 *
 * `classifyWorkerEnd` used to run here, over issues this module fetched with `bsc plan list` and a
 * coord fold it read itself. Both inputs were already Rust's — plan.db owns the statuses, coord.log
 * owns the landed tiebreaker — so the verdict was the only part in the renderer, and a decision about
 * a backend-owned resource that stops happening when the webview dies is the idle-reaper failure.
 *
 * BATCHED, and that is not an optimization detail. The idle sweep below evaluates every live worker on
 * each of three log streams' changes; a per-pane invoke there is the exact shape #3908 and #3954 were
 * filed to undo. Rust reads plan.db and coord.log ONCE for the whole list.
 *
 * `null` at a position means the project has NO plan store — the caller must bail rather than end the
 * pane. A stream that simply owns nothing still gets a verdict (`needs-attention`), because completion
 * cannot be confirmed from an empty set. Those two are different answers and must not be collapsed.
 */
async function workerEndVerdicts(
  projectKey: string,
  streamIds: string[],
): Promise<(WorkerEndVerdict | null)[]> {
  if (streamIds.length === 0) return [];
  const got = await safeInvoke<(WorkerEndVerdict | null)[] | null>(
    "worker_end_verdicts",
    { projectKey, streamIds },
    null,
    (e) => log.error(`auto-end: worker_end_verdicts failed for ${projectKey}: ${e}`),
  );
  // A failed invoke is the same as an unreadable store: unknown, so every caller bails. Index-aligned
  // either way — a short result would attribute one worker's verdict to another.
  if (!Array.isArray(got) || got.length !== streamIds.length) return streamIds.map(() => null);
  return got;
}

async function evaluateExit(
  paneId: string,
  opts: { kill?: boolean; exit?: SessionEndPayload } = {},
): Promise<void> {
  const s = useAppStore.getState();
  if (s.endedPanes[paneId]) return; // already ended
  if ((s.paneRoles[paneId] ?? "worker") !== "worker") return; // only auto-end workers
  const stream = s.fleetPaneStreams[paneId];
  if (!stream) return;

  // The owning project key, from the tab that minted this pane id. The old positional
  // `t{tab}p{pane}` parse broke for fleet workers (#1379): #1176 gave them stable
  // `<projectKey>:<streamId>` ids, so look the pane up in its tab's `paneIds` instead.
  const projectKey = s.tabs.find((t) => t.paneIds?.includes(paneId))?.projectKey;
  if (!projectKey) return; // can't query the DB without the project

  // ONE call to Rust, which reads plan.db and folds coord.log itself. `null` means there is no plan
  // store to read, and bailing on it is the same refusal the old `if (!issues) return` made — a pane
  // must not be ended on the strength of a missing file.
  const [verdict] = await workerEndVerdicts(projectKey, [stream.id]);
  if (!verdict) return;
  log.info(`auto-end: ${paneId} (${stream.id}) → ${verdict.state} — ${verdict.summary}`);
  useAppStore.getState().markPaneEnded(paneId, {
    state: verdict.state, streamId: stream.id, summary: verdict.summary, at: Date.now(),
    // WHY THE EXIT TRAVELS WITH THE VERDICT. These answer two different questions and both belong on
    // the card: the verdict says whether the LANE is done (from plan.db), the exit says HOW THE
    // PROCESS ENDED (from Rust). Reporting only the first is what made a cage that never started, an
    // agent that crashed, and a worker that genuinely finished all render as "finished its work".
    exit: opts.exit,
  });
  // The director close-open-issues nudge (#1379) USED TO BE HERE and is gone
  // (#the-fleet-went-pull-but-nobody-told-the-director-to-pull). It typed a message into the
  // director's stdin with a trailing CR, which submits it — opening a Claude turn in a session
  // nobody clicked. That is the symptom the maintainer reported, arriving through the one path the
  // injector ratchet could not see (it matches `injectPrompt` imports; this was a raw `pty_write`).
  //
  // NOTHING REPLACES IT, deliberately. It told the director to run `gh issue close`, and the
  // GitHub-ownership clause was removed from director-protocol.md under local-first — the protocol
  // tests now assert its ABSENCE. So the nudge instructed work the director no longer claims.
  // bsc-done (#1379): the worker is still live and asked to close, so actually kill its PTY.
  if (opts.kill) {
    await safeInvoke("pty_kill", { paneId }, undefined, (e) => log.error(`auto-end: pty_kill failed for ${paneId}: ${e}`));
  }
}

/** Resolves a pane's identity id from its tab + grid position — `paneIdFor` from
 *  `@/app/console/lib/paneIdentity`, injected by the caller (App.tsx) so this shared module never
 *  imports app/ as a VALUE (#1626/#1703) — the same inversion `ActivityRow` above already uses for
 *  the app-owned `logs::PaneActivity` shape. */
export type PaneIdResolver = (tab: PaneIdentityTab | undefined, tabIdx: number, paneIdx: number) => string;

export function useWorkerAutoEnd(resolvePaneId: PaneIdResolver): void {
  // Re-subscribe whenever the fleet pane set changes (panes come and go across launches).
  const fleetPaneStreams = useAppStore((s) => s.fleetPaneStreams);
  useEffect(() => {
    let cancelled = false;
    const unlistens: Array<() => void> = [];
    for (const paneId of Object.keys(fleetPaneStreams)) {
      if ((useAppStore.getState().paneRoles[paneId] ?? "worker") !== "worker") continue;
      // THE PAYLOAD IS THE POINT. Rust classifies the exit precisely and sends it here
      // (`SessionEnd { reason, detail, lastOutput }`); this listener used to not even name the
      // argument, so every exit reached the card as `auto-ended` — "finished its work" — whatever
      // had actually happened to it.
      void listen<SessionEndPayload>(`pty_exit_${paneId}`, (e) => {
        if (!cancelled) void evaluateExit(paneId, { exit: e.payload });
      })
        .then((off) => { if (cancelled) off(); else unlistens.push(off); });
    }
    return () => { cancelled = true; for (const off of unlistens) off(); };
  }, [fleetPaneStreams]);

  // bsc-done self-close (#1379): poll the workers that self-reported done and reap each —
  // classify from plan.db (markPaneEnded) AND pty_kill the still-live shell. The endedPanes guard
  // in evaluateExit makes this idempotent across polls (a lingering done.log line won't re-kill).
  // Event-driven (#3638): reap self-reported-done workers only when the done log changes (plus mount +
  // a slow backstop), instead of polling every 2s. The `endedPanes` guard in `evaluateExit` keeps it
  // idempotent, so a lingering done.log line re-firing on a later event won't re-kill.
  useLogStream("done", async (isCancelled) => {
    const done = await logsDonePanes();
    if (isCancelled() || !Array.isArray(done)) return;
    const s = useAppStore.getState();
    for (const paneId of done) {
      if (s.endedPanes[paneId] || !s.fleetPaneStreams[paneId]) continue;
      await evaluateExit(paneId, { kill: true });
    }
  }, []);

  // Idle close-nudge (#1379 stage 3): for each at-rest worker, decide via the pure core whether to
  // nudge it to self-close. A worker that's question-free, idle past the short window, and whose
  // owned issues all read complete in plan.db gets ONE "wrap up / bsc-done" prompt; the nudge
  // re-arms when its turn reopens. A worker paused for the user (coord.waiting) is left alone, and
  // an outstanding director question routes to the resurface path (stage 4), never a close.
  const nudgedRef = useRef<Set<string>>(new Set());
  const resurfacedRef = useRef<Set<string>>(new Set()); // lost-ask resurfaces, one per stale ask
  useLogStream(["activity", "coord", "done"], async (isCancelled) => {
    const activity = await logsPaneActivity<ActivityRow>();
    const coordRes = await readCoordState(5000);
    if (isCancelled() || !Array.isArray(activity)) return;
    const coord = coordRes?.state ?? emptyCoordState();
    const s = useAppStore.getState();
    const now = Date.now();
    // THE PANE THE USER IS IN, by identity. `resolvePaneId` (the app's `paneIdFor`) is what maps
    // (tab, index) to the id a fleet pane actually carries — comparing against a positional
    // `t{tab}p{idx}` string would never match one, which is how the idle reaper's own focus guard came
    // to be inert for exactly these panes.
    const focusedPaneId =
      s.focusedPaneIdx >= 0 && s.tabs[s.activeTabIdx]
        ? resolvePaneId(s.tabs[s.activeTabIdx], s.activeTabIdx, s.focusedPaneIdx)
        : "";

    // #3944: decide the candidate set FIRST, then read each project's issues ONCE.
    //
    // This used to spawn `bsc plan list --stream <id>` inside the loop — one subprocess per pane, awaited
    // serially, on every change to any of THREE log streams (activity/coord/done). That was the bulk of
    // 37 `bsc plan list`/min and ~10% of all invoke time. `useWarden`, in the next file over, already
    // reads once per project and partitions in memory; this now matches it. `PlanIssue` carries `stream`,
    // so the per-stream query bought nothing a filter can't do.
    const candidates: Array<{ paneId: string; stream: { id: string }; projectKey: string; act: ActivityRow | undefined }> = [];
    for (const paneId of Object.keys(s.fleetPaneStreams)) {
      if (s.endedPanes[paneId] || (s.paneRoles[paneId] ?? "worker") !== "worker") continue;
      const act = activity.find((a) => a.pane === paneId);
      if (act?.state === "run") { nudgedRef.current.delete(paneId); resurfacedRef.current.delete(paneId); continue; } // working → re-arm
      if (coord.waiting.some((w) => w.session === paneId)) continue;             // paused for the user → leave it
      // `maintaining` NO LONGER PINS A PANE OPEN (#session-stop-is-honoured). Under #1957 a `maintain`
      // event meant "parked alive and ready", so skipping it was right. It now means the worker left a
      // standing note on its way OUT, so skipping it would hold a finished pane in the grid forever —
      // the resting-state problem (#920) coming back through the event that says the work is done.
      if (!coord.asking.some((a) => a.session === paneId)) resurfacedRef.current.delete(paneId); // ask answered → re-arm resurface
      const stream = s.fleetPaneStreams[paneId];
      const projectKey = s.tabs.find((t) => t.paneIds?.includes(paneId))?.projectKey;
      if (!projectKey || !stream) continue;
      candidates.push({ paneId, stream, projectKey, act });
    }
    if (candidates.length === 0) return;
    // One BATCHED call per distinct project (#3944, now in Rust): plan.db and coord.log are read once
    // per project rather than once per pane, and the classification happens where both already live.
    // The verdicts come back index-aligned to the streams asked about, so a pane can only ever be
    // matched with its own.
    const byProject = new Map<string, Map<string, WorkerEndVerdict>>();
    await Promise.all([...new Set(candidates.map((c) => c.projectKey))].map(async (key) => {
      const streams = candidates.filter((c) => c.projectKey === key).map((c) => c.stream.id);
      const verdicts = await workerEndVerdicts(key, streams);
      const m = new Map<string, WorkerEndVerdict>();
      streams.forEach((sid, i) => { const v = verdicts[i]; if (v) m.set(sid, v); });
      byProject.set(key, m);
    }));
    if (isCancelled()) return;

    for (const { paneId, stream, projectKey, act } of candidates) {
      const verdict = byProject.get(projectKey)?.get(stream.id);
      if (!verdict) continue;                               // no plan.db / read failed — same bail as before
      const action = decideWorkerAutoEnd({
        focused: paneId === focusedPaneId,
        turnOpen: act?.state === "run",
        idleMs: act?.state === "idle" ? now - act.at : 0,
        hasOutstandingQuestion: coord.asking.some((a) => a.session === paneId),
        verdict,
      }, DEFAULT_AUTO_END_THRESHOLDS);
      if (action === "close-nudge" && !nudgedRef.current.has(paneId)) {
        // The decision is unchanged — this worker is at rest with its owned work complete. What we DO
        // with it changed: reap the pane ourselves rather than typing at the session (see the header).
        // `evaluateExit` re-reads plan.db and is idempotent via its own `endedPanes` guard, so the ref
        // is belt-and-braces against a burst of log events, not the thing that makes it safe.
        // No `kill` — the shell stays up so the user can resume this session with a click.
        nudgedRef.current.add(paneId); // once per idle period; cleared when the turn reopens
        log.info(`auto-end: reaping ${paneId} (${stream.id}) — idle + work complete`);
        await evaluateExit(paneId);
      } else if (action === "resurface-question" && !resurfacedRef.current.has(paneId)) {
        // Lost-question resurface (#1379 stage 4): the worker has waited too long on a director
        // answer. This used to TYPE the question into the director's pane; it now only records the
        // observation (#the-fleet-went-pull-but-nobody-told-the-director-to-pull).
        //
        // NOTHING IS LOST, because the push had a pull all along: `bsc logs waiting` lists every
        // unanswered ask oldest-first, and the director's protocol now tells it to sweep that queue.
        // The pull is strictly better than this was — it shows EVERY stale ask on every sweep, where
        // this fired once per pane per idle period and then went quiet.
        const ask = coord.asking.find((a) => a.session === paneId);
        if (ask) {
          resurfacedRef.current.add(paneId);
          const waited = Math.max(1, Math.round((now - ask.at) / 60_000));
          log.info(`auto-end: ${paneId} has waited ~${waited}m on an unanswered ask — it is in \`bsc logs waiting\` for its director to sweep`);
        }
      }
    }
  }, []);

  // Reclaim a finished worker's worktree once its branch is MERGED (#worktree-disk). Gated on the
  // pane already being ENDED (its work is pushed) AND the PR merged on GitHub — the authoritative
  // remote signal the boot-GC's local merge check can't see. Teardown runs once per pane; the
  // boot-GC remains the fallback for anything missed (and never removes a dirty/unmerged worktree).
  // Per-pane probe state (#an-unmerged-ended-pane-is-polled-against-github-forever). This used to be
  // a Set written ONLY on the success path, so a pane whose PR never merged — or that never had one —
  // was re-queried every 60s for the life of the app: measured at 30 `github_request` invokes per
  // minute across 31 ended panes, ~1800 API calls an hour asking a question whose answer had not
  // changed. `merged` is the terminal state and is what the old Set expressed, except now three
  // different verdicts can reach it instead of only "merged".
  //
  // THE SCHEDULE LIVES IN THE STORE, NOT A `useRef` (#180). `endedPanes` is persisted, but the
  // backoff that decides whether to re-ask about one is not the same thing twice: a `useRef` starts
  // empty on every remount, so a restart forgot every pane's progress and re-asked GitHub about all
  // of them from attempt zero — including panes already `nextAt: null` (settled: merged, or given up
  // on after `NO_PR_ATTEMPTS`). `panePrProbes` persists alongside `endedPanes` for exactly that
  // reason, and `reopenPane`/`clearEndedPanes` drop a pane's entry when it stops being "ended", so a
  // pane that ends again later starts a fresh backoff rather than resuming a stale one.
  usePoll(async (isCancelled) => {
    const s = useAppStore.getState();
    const token = s.githubToken;
    if (!token) return;
    const now = Date.now();
    for (const paneId of Object.keys(s.endedPanes)) {
      const probe = s.panePrProbes[paneId];
      if (probe && probe.nextAt === null) continue;   // settled — merged, or given up on
      if (probe && !isDue(probe.nextAt ?? undefined, now)) continue; // backing off
      if ((s.paneRoles[paneId] ?? "worker") !== "worker") continue;
      const ps = s.paneStream[paneId];               // { repo, branch }
      const stream = s.fleetPaneStreams[paneId];      // AgentStream (.id = the worktree slug source)
      const projectKey = s.tabs.find((t) => t.paneIds?.includes(paneId))?.projectKey;
      if (!ps || !stream || !projectKey) continue;
      const owner = ps.repo.split("/")[0];
      const prs = await safeInvoke<unknown>(
        "github_request",
        { token, path: `repos/${ps.repo}/pulls?state=all&head=${owner}:${ps.branch}&per_page=1` },
        null,
      );
      if (isCancelled()) return;
      const verdict = verdictFromPulls(prs);
      const attempts = probe?.attempts ?? 0;
      const plan = planNextProbe(verdict, attempts);
      useAppStore.getState().setPanePrProbe(paneId, {
        attempts: attempts + (plan.countsAsAttempt ? 1 : 0),
        nextAt: plan.retryInMs === null ? null : Date.now() + plan.retryInMs,
      });
      if (verdict !== "merged") continue; // open / none / unknown — the plan above decides when to re-ask
      log.info(`teardown: stream ${stream.id} merged → reclaiming its worktree`);
      await safeInvoke("teardown_worktree", { projectKey, repo: ps.repo, agentId: stream.id }, undefined,
        (e) => log.error(`teardown_worktree failed for ${stream.id}: ${e}`));
    }
  }, 60_000, []);
}

